def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    # Complete the straight lines through collinear pairs of 3 markers.
    # Each source 3 is recolored 4; newly completed line cells are 3.
    for r, c in pts:
        out[r][c] = 4
    for i, (r1, c1) in enumerate(pts):
        for r2, c2 in pts[i + 1:]:
            dr, dc = r2-r1, c2-c1
            if dr == 0:
                step_r, step_c = 0, 1 if dc > 0 else -1
            elif dc == 0:
                step_r, step_c = (1 if dr > 0 else -1), 0
            elif abs(dr) == abs(dc):
                step_r, step_c = (1 if dr > 0 else -1), (1 if dc > 0 else -1)
            else:
                continue
            # Only extend complete straight line from the pair in both directions.
            y, x = r1, c1
