    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    edge_cells = set()
    for c in range(w):
        if grid[0][c] != background: edge_cells.add((0, c))
        if grid[h-1][c] != background: edge_cells.add((h-1, c))
    for r in range(h):
        if grid[r][0] != background: edge_cells.add((r, 0))
        if grid[r][w-1] != background: edge_cells.add((r, w-1))
